contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address from, uint256 id, bytes calldata data) public payable {
        bytes4 ret;
        bool reverted;
        try c.onERC721Received(sender, from, id, data) returns (bytes4 r) {
            ret = r;
            reverted = false;
        } catch {
            ret = bytes4(0);
            reverted = true;
        }
        assert(reverted || ret == 0x150b7a02);
    }

    receive() external payable {}
}

