pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function _run(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) internal {
        _feeRate = uint16(bound(uint256(_feeRate), 0, 5000));
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {} catch { return; }
        assertTrue(c.nft() == _nft);
    }

    function testFuzz_run(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        vm.assume(_baseToken.code.length == 0 && uint160(_baseToken) > 0xffff && _baseToken != address(this) && _baseToken != address(c) && _baseToken != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _baseToken != 0x000000000000000000636F6e736F6c652e6c6f67 && _baseToken != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _baseToken != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
